```tsx
import "./TimeList.css";

export type TimeState = "past" | "next" | "later";

export interface TimeItem {
  id: string;
  name: string;
  time: string;
  state: TimeState;
}

export interface TimeListProps {
  items: readonly TimeItem[];
  label?: string;
}

const STATUS_TEXT: Record<TimeState, string> = {
  past: "Passed",
  next: "Next",
  later: "Later",
};

export function TimeList({ items, label = "Times through the day" }: TimeListProps) {
  return (
    <ol className="time-list" aria-label={label}>
      {items.map((item) => (
        <li
          key={item.id}
          className={`time-list__item is-${item.state}`}
          tabIndex={0}
          aria-current={item.state === "next" ? "time" : undefined}
        >
          <span className="time-list__name">
            {item.name}
            <span
              className={
                item.state === "next" ? "time-list__status" : "time-list__status sr-only"
              }
            >
              {STATUS_TEXT[item.state]}
            </span>
          </span>
          <time className="time-list__time">{item.time}</time>
        </li>
      ))}
    </ol>
  );
}
```

```css
.time-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  font: inherit;
  color: var(--ink);
  background: var(--slide);
}

.time-list__item {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1em;
  padding: clamp(0.6rem, 1.2vw, 0.9rem) clamp(0.75rem, 1.5vw, 1.25rem);
  border-bottom: 1px solid var(--hair);
  border-left: 3px solid transparent;
  color: var(--ink);
  font-size: clamp(1rem, 1.6vw, 1.35rem);
}

.time-list__item:last-child {
  border-bottom: none;
}

.time-list__item.is-past {
  color: var(--muted);
}

.time-list__item.is-next {
  background: var(--cresyl-wash);
  border-left-color: var(--cresyl);
  font-weight: 600;
}

.time-list__item:focus-visible {
  border-bottom-color: var(--cresyl);
}

.time-list__name {
  display: inline-flex;
  align-items: baseline;
  gap: 0.6em;
}

.time-list__status {
  font-size: 0.65em;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--cresyl);
}

.time-list__time {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
